create database [Ubaid Qaida]
use [Ubaid Qaida]
---Units Table
create table units(
unitno int primary key,
unitTitle varchar(max)

)




-----Lessons Table
CREATE TABLE Lessons (
    unitno INT,
    lessonNo INT,
    Title NVARCHAR(MAX),   -- FIXED (was varchar)
    CONSTRAINT pk_lno PRIMARY KEY (unitno, lessonNo),
    CONSTRAINT fk_uno FOREIGN KEY (unitno) REFERENCES units(unitno)
);
-----Words Table
CREATE TABLE Words(
    unitno INT,
    lessonNo INT,
    wno INT,
    word NVARCHAR(50),   -- IMPORTANT: varchar → NVARCHAR
	Meaning NVARCHAR(50),
    CONSTRAINT pk_wno PRIMARY KEY(unitno, lessonno, wno)
);

create table Students(
Sid int primary key,
fullname varchar(50),
age int,
gender varchar(10),

);

create table QuestionType(
typeNo int primary key,
Type varchar(20),
Description Nvarchar(200)

);

CREATE TABLE Exercise (
    eid INT PRIMARY KEY,
    unitno INT,
    lessonNo INT,
    typeNo INT,

    CONSTRAINT fk_ex_unit FOREIGN KEY (unitno)
        REFERENCES units(unitno),

    CONSTRAINT fk_ex_lesson FOREIGN KEY (unitno, lessonNo)
        REFERENCES Lessons(unitno, lessonNo),

    CONSTRAINT fk_ex_type FOREIGN KEY (typeNo)
        REFERENCES QuestionType(typeNo)
);

CREATE TABLE ExerciseQuestion
(
    unitno INT,
    lessonNo INT,
    eid INT,        -- FK → Exercise
    wno INT,        -- NOT identity
    word NVARCHAR(200),
    solution NVARCHAR(300),

    CONSTRAINT fk_eq_exercise 
        FOREIGN KEY (eid)
        REFERENCES Exercise(eid),

    CONSTRAINT pk_exq 
        PRIMARY KEY (unitno, lessonNo, eid, wno)
);
;

CREATE TABLE StudentAttempt
(
    sid INT,              -- FK → Students
    unitno INT,
    lessonNo INT,
    eid INT,
    wno INT,              -- question number
    answer NVARCHAR(300), -- student ka answer

    -- Primary Key
    CONSTRAINT pk_StudentAttempt
        PRIMARY KEY (sid, unitno, lessonNo, eid, wno),

    -- FK → Students
    CONSTRAINT fk_sa_student
        FOREIGN KEY (sid)
        REFERENCES Students(Sid),

    -- FK → ExerciseQuestion (composite)
    CONSTRAINT fk_sa_exercisequestion
        FOREIGN KEY (unitno, lessonNo, eid, wno)
        REFERENCES ExerciseQuestion(unitno, lessonNo, eid, wno)
);
