INSERT INTO Words (unitno, lessonNo, wno, word, meaning) VALUES
(2,11,1,  N'أَنَّ الله',                    N'خدا ہے'),
(2,11,2,  N'أَنَّ الرَّسُولَ',               N'کہ رسول'),
