(2,11,10, N'أن صالحا',                      N'یہ درست ہے'),
(2,11,11, N'وَأَنَّ الْمَسَاجِدَ',           N'اور یہ کہ مساجد'),
(2,11,12, N'أَنَّ الْفُلْكَ',               N'وہ صندوق'),
(2,11,13, N'أَنَّ الحق لله',                 N'سچائی خدا کی ہے۔'),
(2,11,14, N'أَنَّ اللهَ بَرِي',              N'خدا راستباز ہے۔'),
(2,11,15, N'وَأَنَّ السَّاعَةَ آتِيَةُ',     N'اور وہ وقت آنے والا ہے۔'),
(2,11,16, N'أَنَّ الرَّسُولَ حَقٌّ',         N'رسول سچا ہے۔'),
(2,11,17, N'أَنَّ الْقُوَّةَ لِلهِ جَمِيعًا', N'کہ قدرت سب اللہ کی ہے۔'),
(2,11,18, N'وَأَنَّ الْمَسَاجِدَ لِلهِ',      N'اور مسجدیں خدا کی ہیں۔'),
(2,11,19, N'وَأَنَّ اللهَ سَمِيعٌ عَلِيمٌ',   N'اور یہ کہ خدا سب کچھ سننے والا اور سب کچھ جاننے والا ہے۔'),
(2,11,20, N'أَنَّ اللهَ سَمِيعٌ عَلِيمٌ',    N'خدا سب کچھ سننے والا، سب کچھ جاننے والا ہے۔'),
(2,11,21, N'أَنَّ اللهَ غَنِيٌّ حَمِيدٌ',     N'خدا غنی اور قابل تعریف ہے۔'),
(2,11,22, N'أَنَّ اللهَ غَفُورٌ حَلِيمٌ',     N'خدا بخشنے والا، بردبار ہے۔'),
(2,11,23, N'أَنَّ اللهَ عَزِيزٌ حَكِيمٌ',     N'خدا غالب، حکمت والا ہے۔'),
(2,11,24, N'وَأَنَّ اللهَ تَوَّابُ حَكِيمُ',   N'اور یہ کہ خدا توبہ کرنے والا اور حکمت والا ہے۔'),
(2,11,25, N'وَأَنَّ اللَّهَ سَمِيعٌ بَصِيرٌ',  N'اور خدا سب کچھ سننے والا اور سب کچھ دیکھنے والا ہے۔'),
(2,11,26, N'وَأَنَّ اللَّهَ رَءُوفٌ رَحِيمٌ',  N'اور یہ کہ خدا غفور و رحیم ہے۔'),
(2,11,27, N'أَنَّ صَالِحًا مُرْسَل',          N'بھیجا گیا');



