(2,12,31, N'وَكَانَ اللهُ / سَمِيعًا عَلِيمًا',       N'اور اللہ سب کچھ سننے والا جاننے والا ہے۔'),
(2,12,32, N'إِنَّ اللهَ كَانَ / عَلِيمًا حَكِيمًا',    N'خدا سب کچھ جاننے والا، حکمت والا ہے۔'),
(2,12,33, N'إِنَّ اللهَ كَانَ / تَوَّابًا رَحِيمًا',   N'خدا بخشنے والا اور مہربان ہے۔'),
(2,12,34, N'إِنَّ اللهَ كَانَ / عَلِيًّا كَبِيرًا',    N'خدا سب سے اعلی، عظیم تھا۔'),
(2,12,35, N'إِنَّ اللهَ كَانَ / عَفُوا غَفُورًا',     N'بے شک اللہ بخشنے والا ہے۔'),
(2,12,36, N'فَإِنَّ اللَّهَ كَانَ / غَفُورًا رَحِيمًا', N'بے شک اللہ بخشنے والا مہربان ہے۔'),
(2,12,37, N'وَكَانَ الْإِنْسَانُ / كَفُورًا',         N'ناشکرا'),
(2,12,38, N'وَكَانَ الْإِنْسَانُ / قَتُورًا',         N'بخیل'),
(2,12,39, N'إِنَّ الْعَهْدَ / كَانَ مَسْئُولًا',      N'عہد ذمہ دار تھا۔'),
(2,12,40, N'إِنَّ الشَّيْطَانَ / كَانَ لِلْإِنسَانِ عَدُوا', N'شیطان انسان کا دشمن تھا۔'),
(2,12,41, N'كانَ ذلِكَ / فِي الْكِتَابِ / مَسْطُورًا', N'تحریر کردہ'),
(2,12,42, N'إِنَّ اللهَ كَانَ / عَلِيمًا خَبِيرًا',   N'خدا سب کچھ جاننے والا اور باخبر ہے۔'),
(2,12,43, N'إِنَّ اللهَ كَانَ / سَمِيعًا بَصِيرًا',   N'خدا سننے والا، سب کچھ دیکھنے والا ہے۔'),
(2,12,44, N'وَكَانَ الْإِنْسَانُ عَجُولًا',          N'جلد باز'),
(2,12,45, N'إِنَّ الْبَاطِلَ / كَانَ زَهُوقًا',       N'مٹ جانے والا'),
(2,12,46, N'إِنَّ الشَّيْطَانَ / كَانَ لِلرَّحْمَانِ عَصِيَّا', N'شیطان رحمن کا نافرمان تھا۔'),
(2,12,47, N'مَا كَانَ إِبْرَاهِيمُ / يَهُودِيًا وَلَا نَصْرَانِيًّا / وَلَكِنْ كَانَ حَنِيفًا مُسْلِمًا', 
            N'ابراہیم نہ یہودی تھا نہ عیسائی بلکہ راست باز مسلمان تھے۔');


