INSERT INTO ExerciseQuestion (unitno, lessonNo, eid, wno, word, solution) VALUES
-- =============================================
-- Q1: Sentence Translation (Single and Double Attributes)
-- =============================================
(1, 14, 77, 1, N'وَاللّٰهُ غَفُوْرٌ', N'اور اللہ غفور ہے'),
(1, 14, 77, 2, N'وَاللّٰهُ سَمِيْعٌ', N'اور اللہ سننے والا ہے'),
(1, 14, 77, 3, N'وَاللّٰهُ وَاسِعٌ', N'اور اللہ وسعت والا ہے'),
(1, 14, 77, 4, N'وَاللّٰهُ شَهِيْدٌ', N'اور اللہ گواہ ہے'),
(1, 14, 77, 5, N'وَاللّٰهُ غَنِيٌّ', N'اور اللہ غنی ہے'),
(1, 14, 77, 6, N'وَاللّٰهُ شَكُوْرٌ', N'اور اللہ قدردان ہے'),
(1, 14, 77, 7, N'وَاللّٰهُ عَزِيْزٌ', N'اور اللہ عزیز ہے'),
(1, 14, 77, 8, N'وَاللّٰهُ قَدِيْرٌ', N'اور اللہ قدرت والا ہے'),
(1, 14, 77, 9, N'وَاللّٰهُ مُحِيْطٌ', N'اور اللہ گھیرنے والا ہے'),
(1, 14, 77, 10, N'وَاللّٰهُ عَلِيْمٌ', N'اور اللہ علیم ہے'),
(1, 14, 77, 11, N'وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ', N'اور اللہ معاف کرنے والا اور رحم کرنے والا ہے'),
(1, 14, 77, 12, N'وَاللّٰهُ سَمِيْعٌ عَلِيْمٌ', N'اور اللہ سننے والا اور علیم ہے'),
(1, 14, 77, 13, N'وَاللّٰهُ غَفُوْرٌ حَلِيْمٌ', N'اور اللہ بخشنے والا اور بردبار ہے'),
(1, 14, 77, 14, N'وَاللّٰهُ وَاسِعٌ عَلِيْمٌ', N'اور اللہ وسعت والا اور علیم ہے'),
(1, 14, 77, 15, N'وَاللّٰهُ غَنِيٌّ حَلِيْمٌ', N'اور اللہ غنی اور حلیم ہے'),
(1, 14, 77, 16, N'وَاللّٰهُ عَزِيْزٌ حَكِيْمٌ', N'اور اللہ عزت والا اور حکیم ہے'),
(1, 14, 77, 17, N'وَاللّٰهُ شَكُوْرٌ حَلِيْمٌ', N'اور اللہ قدردان اور حلیم ہے'),
(1, 14, 77, 18, N'وَاللّٰهُ عَلِيْمٌ حَكِيْمٌ', N'اور اللہ علیم اور حکیم ہے'),
(1, 14, 77, 19, N'وَاللّٰهُ غَنِيٌّ حَمِيْدٌ', N'اور اللہ غنی اور قابلِ تعریف ہے');

INSERT INTO ExerciseQuestion (unitno, lessonNo, eid, wno, word, solution) VALUES
-- =============================================
-- Q1: Highlight small phrases with "Haza" (eid 78)
-- =============================================
(1, 15, 78, 1, N'سُبْحَانَكَ هٰذَا بُهْتَانٌ عَظِيمٌ', N'هٰذَا بُهْتَانٌ'),
(1, 15, 78, 2, N'هٰذَا سِحْرٌ وَإِنَّا بِهِ كَافِرُونَ', N'هٰذَا سِحْرٌ'),
(1, 15, 78, 3, N'يَغْشَى النَّاسَ ۖ هٰذَا عَذَابٌ أَلِيمٌ', N'هٰذَا عَذَابٌ'),
(1, 15, 78, 4, N'هٰذَا هُدًى ۖ وَالَّذِينَ كَفَرُوا', N'هٰذَا هُدًى'),
(1, 15, 78, 5, N'فَسَيَقُولُونَ هٰذَا إِفْكٌ قَدِيمٌ', N'هٰذَا إِفْكٌ'),
(1, 15, 78, 6, N'وَاتَّبِعُونَ ۚ هٰذَا صِرَاطٌ مُّسْتَقِيمٌ', N'هٰذَا صِرَاطٌ'),
(1, 15, 78, 7, N'وَهٰذَا كِتَابٌ مُّصَدِّقٌ', N'هٰذَا كِتَابٌ'),
(1, 15, 78, 8, N'هٰذَا نَذِيرٌ مِّنَ النُّذُرِ الْأُولَىٰ', N'هٰذَا نَذِيرٌ'),
(1, 15, 78, 9, N'فَقَالَ الْكَافِرُونَ هٰذَا شَيْءٌ عَجِيبٌ', N'هٰذَا شَيْءٌ'),

-- =============================================
-- Q2: Highlight "Haza" followed by "Al-" (eid 79)
-- =============================================
(1, 15, 79, 1, N'وَهٰذَا النَّبِيُّ وَالَّذِينَ آمَنُوا', N'هٰذَا النَّبِيُّ'),
(1, 15, 79, 2, N'لَوْلَا نُزِّلَ هٰذَا الْقُرْآنُ', N'هٰذَا الْقُرْآنُ'),
(1, 15, 79, 3, N'لِلنَّاسِ فِي هٰذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ', N'هٰذَا الْقُرْآنِ'),
(1, 15, 79, 4, N'أَنْ أَكُونَ مِثْلَ هٰذَا الْغُرَابِ', N'هٰذَا الْغُرَابِ'),
(1, 15, 79, 5, N'وَأُوحِيَ إِلَيَّ هٰذَا الْقُرْآنُ', N'هٰذَا الْقُرْآنُ'),
(1, 15, 79, 6, N'وَيَقُولُونَ مَتَىٰ هٰذَا الْفَتْحُ', N'هٰذَا الْفَتْحُ'),
(1, 15, 79, 7, N'وَيَقُولُونَ مَتَىٰ هٰذَا الْوَعْدُ', N'هٰذَا الْوَعْدُ'),
(1, 15, 79, 8, N'إِنَّ هٰذَا الْقُرْآنَ يَقُصُّ', N'هٰذَا الْقُرْآنَ'),
(1, 15, 79, 9, N'مَالِ هٰذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ', N'هٰذَا الرَّسُولِ');



