INSERT INTO QuestionType(typeNo, Type, Description) VALUES
(16, 'Highlight_Demonstrative', N'درج ذیل آیات میں سے اس حصے کو پہلی مثال کی طرح نمایاں کریں جس میں (هٰذَا) اور اس کے بعد لفظ سے چھوٹا قرآنی جملہ بن رہا ہے۔'), --
(17, 'Highlight_Demonstrative_Al', N'درج ذیل آیات میں سے صرف اس حصے کو پہلی مثال کی طرح نمایاں کریں جس میں (هٰذَا) اور اس کے بعد (ال) والا لفظ ہے۔'); 

INSERT INTO QuestionType(typeNo, Type, Description) VALUES
(18, 'Highlight_That', N'درج ذیل آیات میں سے اس حصے کو پہلی مثال کی طرح نمایاں کریں جس میں (ذٰلِكَ) اور اس کے بعد والے لفظ سے قرآنی جملہ بن رہا ہے۔'), --
(19, 'Highlight_That_Al', N'درج ذیل آیات میں (ذٰلِكَ) اور اس کے بعد (ال) والے لفظ سے قطعہ یا جملہ بننے والے حصہ کو پہلی مثال کی طرح نمایاں کریں۔'); --


INSERT INTO ExerciseQuestion (unitno, lessonNo, eid, wno, word, solution) VALUES
-- =============================================
-- Q1: Highlight phrases with "Thalika" (eid 80)
-- =============================================
(1, 16, 80, 1, N'ذٰلِكَ يَوْمٌ مَّشْهُودٌ', N'ذٰلِكَ يَوْمٌ'),
(1, 16, 80, 2, N'ذٰلِكَ عِيْسَى ابْنُ مَرْيَمَ', N'ذٰلِكَ عِيْسَى'),
(1, 16, 80, 3, N'ذٰلِكَ خَيْرٌ وَأَحْسَنُ', N'ذٰلِكَ خَيْرٌ'),
(1, 16, 80, 4, N'ذٰلِكَ يَوْمٌ مَّجْمُوْعٌ لَّهُ النَّاسُ', N'ذٰلِكَ يَوْمٌ'),
(1, 16, 80, 5, N'ذٰلِكَ خَيْرٌ ذٰلِكَ مِنْ آيَاتِ اللّٰهِ', N'ذٰلِكَ خَيْرٌ'),
(1, 16, 80, 6, N'ذٰلِكَ وَعْدٌ غَيْرُ مَكْذُوْبٍ', N'ذٰلِكَ وَعْدٌ'),
(1, 16, 80, 7, N'ذٰلِكَ ذِكْرٰى لِلذَّاكِرِيْنَ', N'ذٰلِكَ ذِكْرٰى'),
(1, 16, 80, 8, N'ذٰلِكَ تَخْفِيْفٌ مِّن رَّبِّكُمْ', N'ذٰلِكَ تَخْفِيْفٌ'),
(1, 16, 80, 9, N'ذٰلِكَ حَشْرٌ عَلَيْنَا يَسِيْرٌ', N'ذٰلِكَ حَشْرٌ'),

-- =============================================
-- Q2: Highlight "Thalika" followed by "Al-" (eid 81)
-- =============================================
(1, 16, 81, 1, N'ذٰلِكَ الْكِتَابُ لَا رَيْبَ فِيْهِ', N'ذٰلِكَ الْكِتَابُ'),
(1, 16, 81, 2, N'ذٰلِكَ الْخِزْيُ الْعَظِيْمُ', N'ذٰلِكَ الْخِزْيُ'),
(1, 16, 81, 3, N'وَذٰلِكَ الْفَوْزُ الْعَظِيْمُ', N'ذٰلِكَ الْفَوْزُ'),
(1, 16, 81, 4, N'ذٰلِكَ الْفَضْلُ مِنَ اللّٰهِ', N'ذٰلِكَ الْفَضْلُ'),
(1, 16, 81, 5, N'وَذٰلِكَ الْفَوْزُ الْمُبِيْنُ', N'ذٰلِكَ الْفَوْزُ'),
(1, 16, 81, 6, N'ذٰلِكَ الدِّيْنُ الْقَيِّمُ', N'ذٰلِكَ الدِّيْنُ'),
(1, 16, 81, 7, N'ذٰلِكَ الْخِزْيُ الْعَظِيْمُ', N'ذٰلِكَ الْخِزْيُ'),
(1, 16, 81, 8, N'وَقَضَيْنَا إِلَيْهِ ذٰلِكَ الْأَمْرَ', N'ذٰلِكَ الْأَمْرَ'),
(1, 16, 81, 9, N'ذٰلِكَ الْيَوْمُ الَّذِي كَانُوا', N'ذٰلِكَ الْيَوْمُ'),
(1, 16, 81, 10, N'ذٰلِكَ الْيَوْمُ الْحَقُّ', N'ذٰلِكَ الْيَوْمُ'),
(1, 16, 81, 11, N'فَوَقَاهُمُ اللّٰهُ شَرَّ ذٰلِكَ الْيَوْمِ', N'ذٰلِكَ الْيَوْمِ');


INSERT INTO QuestionType(typeNo, Type, Description) VALUES
