INSERT INTO ExerciseQuestion (unitno, lessonNo, eid, wno, word, solution) VALUES
-- =============================================
-- Q1: Highlight phrases with "Hazihi" or "Tilka" (eid 82)
-- =============================================
(1, 17, 82, 1, N'هٰذِهِ نَاقَةٌ لَّهَا شِرْبٌ', N'هٰذِهِ نَاقَةٌ'),
(1, 17, 82, 2, N'هٰذِهِ نَاقَةُ اللّٰهِ لَكُمْ آيَةً', N'هٰذِهِ نَاقَةُ'),
(1, 17, 82, 3, N'هٰذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ', N'هٰذِهِ جَهَنَّمُ'),
(1, 17, 82, 4, N'إِنَّ هٰذِهِ تَذْكِرَةٌ', N'هٰذِهِ تَذْكِرَةٌ'),
(1, 17, 82, 5, N'هٰذِهِ جَهَنَّمُ الَّتِي يُكَذِّبُ', N'هٰذِهِ جَهَنَّمُ'),
(1, 17, 82, 6, N'إِنَّ هٰذِهِ تَذْكِرَةٌ ۖ فَمَن شَاءَ اتَّخَذَ', N'هٰذِهِ تَذْكِرَةٌ'),
(1, 17, 82, 7, N'تِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ', N'تِلْكَ نِعْمَةٌ'),
(1, 17, 82, 8, N'وَتِلْكَ عَادٌ ۖ جَحَدُوا', N'تِلْكَ عَادٌ'),
(1, 17, 82, 9, N'تِلْكَ عُقْبَى الَّذِينَ اتَّقَوا', N'تِلْكَ عُقْبَى'),

-- =============================================
-- Q2: Highlight "Hazihi"/"Tilka" followed by "Al-" (eid 83)
-- =============================================
(1, 17, 83, 1, N'وَلَا تَقْرَبَا هٰذِهِ الشَّجَرَةَ', N'هٰذِهِ الشَّجَرَةَ'),
(1, 17, 83, 2, N'ادْخُلُوا هٰذِهِ الْقَرْيَةَ', N'هٰذِهِ الْقَرْيَةَ'),
(1, 17, 83, 3, N'أَخْرِجْنَا مِنْ هٰذِهِ الْقَرْيَةِ', N'هٰذِهِ الْقَرْيَةِ'),
(1, 17, 83, 4, N'وَأَتْبِعُوا فِي هٰذِهِ الدُّنْيَا لَعْنَةً', N'هٰذِهِ الدُّنْيَا'),
(1, 17, 83, 5, N'أَحْسَنُوا فِي هٰذِهِ الدُّنْيَا', N'هٰذِهِ الدُّنْيَا'),
(1, 17, 83, 6, N'إِنَّمَا تَقْضِي هٰذِهِ الْحَيَاةَ الدُّنْيَا', N'هٰذِهِ الْحَيَاةَ'),
(1, 17, 83, 7, N'هٰذِهِ النَّارُ الَّتِي كُنْتُمْ بِهَا تُكَذِّبُونَ', N'هٰذِهِ النَّارُ'),
(1, 17, 83, 8, N'أَعْبُدُ رَبَّ هٰذِهِ الْبَلْدَةِ', N'هٰذِهِ الْبَلْدَةِ'),
(1, 17, 83, 9, N'تِلْكَ الْجَنَّةُ الَّتِي نُورِثُ', N'تِلْكَ الْجَنَّةُ');




INSERT INTO QuestionType(typeNo, Type, Description) VALUES
(22, 'Highlight_Emphasis_Lam', N'درج ذیل آیات میں سے صرف اس حصے کو پہلی مثال کی طرح نمایاں کریں جس میں کسی لفظ سے پہلے تاکید کیلئے (لَ) آ رہا ہے۔'), --
(23, 'Highlight_Emphasis_Lam_Al', N'درج ذیل آیات میں تاکید کا لام ایسے لفظ کے شروع میں آ رہا ہے جس کے شروع میں (ال) موجود ہے۔ پہلی مثال کی طرح ایسے حصے کو نمایاں کریں۔'), --
(24, 'Meaning_Emphasis_Lam', N'درج ذیل الفاظ کا مطلب تاکید کے لام کا خیال رکھتے ہوئے کریں۔'); --




