(1, 18, 84, 2, N'وَإِنَّهُ لَحُبِّ الْخَيْرِ لَشَدِيدٌ', N'لَشَدِيدٌ'),
(1, 18, 84, 3, N'إِنَّهُ لَحَقٌّ', N'لَحَقٌّ'),
