(2, 11, 104, 8, N'أَنَّ اللَّهَ سَمِيعٌ عَلِيمٌ', N'کہ اللہ سننے والا جاننے والا ہے'),
(2, 11, 104, 9, N'أَنَّ اللَّهَ غَنِيٌّ حَمِيدٌ', N'کہ اللہ بے نیاز قابل تعریف ہے'),
(2, 11, 104, 10, N'وَأَنَّ اللَّهَ رَؤُوفٌ رَحِيمٌ', N'اور کہ اللہ شفقت اور رحم کرنے والا ہے');

