INSERT INTO QuestionType (TypeNo, Type, Description)
VALUES (42, 'Highlight_Kana_Phrase', N'درج ذیل آیات میں سے اس حصے کو نمایاں کریں جہاں (كَانَ) کے بعد ایک ایسا مکمل جملہ موجود ہے جسے آپ خود سمجھ سکتے ہیں۔');

