INSERT INTO ExerciseQuestion (unitno, lessonNo, eid, wno, word, solution) VALUES
(2, 12, 105, 1, N'فَأُولَٰئِكَ يَتُوبُ اللَّهُ عَلَيْهِمْ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا', N'وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا'),
(2, 12, 105, 2, N'عَسَى اللَّهُ أَنْ يَعْفُوَ عَنْهُمْ وَكَانَ اللَّهُ عَفُوًّا غَفُورًا', N'وَكَانَ اللَّهُ عَفُوًّا غَفُورًا'),
(2, 12, 105, 3, N'وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا', N'كَانَ زَهُوقًا');

