INSERT INTO ExerciseQuestion (unitno, lessonNo, eid, wno, word, solution) VALUES
(2, 12, 105, 4, N'وَتَرْجُونَ مِنَ اللَّهِ مَا لَا يَرْجُونَ وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا', N'وَكَانَ اللَّهُ عَلِيمًا حَكِيمًا'),
(2, 12, 105, 5, N'فَإِنَّ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ غَنِيًّا حَمِيدًا', N'وَكَانَ اللَّهُ غَنِيًّا حَمِيدًا'),
(2, 12, 105, 6, N'وَيَدْعُ الْإِنْسَانُ بِالشَّرِّ دُعَاءَهُ بِالْخَيْرِ وَكَانَ الْإِنْسَانُ عَجُولًا', N'وَكَانَ الْإِنْسَانُ عَجُولًا');

INSERT INTO QuestionType (TypeNo, Type, Description)
VALUES (43, 'Highlight_Vocative_Ya', N'درج ذیل آیات میں اس حصے کو پہلی مثال کی طرح نمایاں کریں جس میں کسی کو (يَا) یا (يَا أَيُّهَا) کے ذریعے پکارا گیا ہے۔');



